questionvariables.text:
/* Randomize inner radius (hub) */
r: rand_with_step(7, 70, 7);

/* Randomize outer radius (rim), guaranteed greater than r */
R: r + rand_with_step(7, 140, 7);

/* Use pi = 3.142 as specified */
Pi_val: 3.142;

/* Intermediate working values, named to match what they represent */
R_sq: R^2;
r_sq: r^2;
diff_sq: R_sq - r_sq;

/* Final area, to be matched to 3 significant figures in the PRT */
A: Pi_val * diff_sq;
